// Tiered honesty ring — resolves the "oracle problem" at the UI layer by showing,
// concentrically, how far each material's claim actually travelled:
//   Tier 1 · Brand claims        — every material has one (ochre)
//   Tier 2 · Supply chain proof  — named supplier + origin on file (indigo)
//   Tier 3 · Third-party audit   — an independent certificate exists (leaf)
window.TT.computeTiers = function computeTiers() {
  const mats = window.TT.passport.materials;
  const n = mats.length;
  let t1 = 0,
    t2 = 0,
    t3 = 0;
  mats.forEach(m => {
    t1++; // a material entry is itself a brand claim
    if (m.supplier && m.supplier !== 'Unknown' && m.origin && m.origin !== 'Not recorded') t2++;
    if ((m.evidence || []).some(e => e.kind === 'cert')) t3++;
  });
  return {
    tier1: {
      pct: Math.round(t1 / n * 100),
      count: t1,
      total: n,
      label: 'Brand claims',
      color: 'var(--ochre-500)'
    },
    tier2: {
      pct: Math.round(t2 / n * 100),
      count: t2,
      total: n,
      label: 'Supply chain proof',
      color: 'var(--indigo-500)'
    },
    tier3: {
      pct: Math.round(t3 / n * 100),
      count: t3,
      total: n,
      label: 'Third-party audit',
      color: 'var(--leaf-600)'
    }
  };
};

